import{_ as s,C as n,o as l,c as d,j as t,a,G as o,a3 as u}from"./chunks/framework.exbasbhr.js";const k=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/getting-started.md","filePath":"en/guide/getting-started.md"}'),h={name:"en/guide/getting-started.md"};function p(g,e,c,m,w,f){const r=n("ArticleMetadata"),i=n("badge");return l(),d("div",null,[e[6]||(e[6]=t("h1",{id:"getting-started",tabindex:"-1"},[a("Getting Started "),t("a",{class:"header-anchor",href:"#getting-started","aria-label":'Permalink to "Getting Started"'},"​")],-1)),o(r),e[7]||(e[7]=t("h2",{id:"system-requirements",tabindex:"-1"},[a("System Requirements "),t("a",{class:"header-anchor",href:"#system-requirements","aria-label":'Permalink to "System Requirements"'},"​")],-1)),t("ul",null,[t("li",null,[o(i,{type:"tip",text:"OS"}),e[0]||(e[0]=a(" Windows 10 1809 (build 17763) or later / Windows 11"))]),t("li",null,[o(i,{type:"warning",text:"Runtime"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("strong",null,".NET 6 Desktop Runtime",-1)),e[3]||(e[3]=a(" (not .NET Framework 4.x)"))]),t("li",null,[o(i,{type:"tip",text:"Memory"}),e[4]||(e[4]=a(" 4GB RAM or more recommended"))]),t("li",null,[o(i,{type:"info",text:"Hardware"}),e[5]||(e[5]=a(" Touch-input supported device (recommended, but not required)"))])]),e[8]||(e[8]=u('<p>See <a href="/website/en/guide/installation">Installation &amp; Update Channels</a> for the full requirements and channel comparison.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Pick an update channel on the <a href="/website/en/download">download page</a>, then choose one of two forms:</p><ul><li><strong>Installer (<code>.exe</code>)</strong>: runs a setup wizard and creates shortcuts — best for devices that stay put</li><li><strong>Portable (<code>.zip</code>)</strong>: extract anywhere and run <code>InkCanvasForClass.exe</code>; writes nothing to the system, ideal for USB sticks and lab deployments</li></ul><p>On the first run, the software guides you through the initial setup.</p><div class="warning custom-block"><p class="custom-block-title">Won&#39;t start?</p><p>If double-clicking does nothing or the window flashes and disappears, you are most likely missing the .NET 6 Desktop Runtime. Download &quot;.NET Desktop Runtime 6.x&quot; for your architecture from Microsoft.</p></div><h2 id="basic-operations" tabindex="-1">Basic Operations <a class="header-anchor" href="#basic-operations" aria-label="Permalink to &quot;Basic Operations&quot;">​</a></h2><h3 id="floating-toolbar" tabindex="-1">Floating Toolbar <a class="header-anchor" href="#floating-toolbar" aria-label="Permalink to &quot;Floating Toolbar&quot;">​</a></h3><p>Once started, you will see a floating toolbar for switching drawing tools and opening settings.</p><p><img src="https://github.com/user-attachments/assets/f47e80a8-05b8-44ab-8c70-6771e97375ea" alt="Floating Toolbar" loading="lazy"></p><p>The toolbar provides these core functions:</p><ul><li>Pen tool: free-hand drawing with pressure support</li><li>Highlighter: semi-transparent annotations</li><li>Eraser: erase by stroke or by lasso</li><li>Color palette: change pen and highlighter colors</li><li>Undo / Redo</li><li>Settings: access application configuration</li><li>Fold / Unfold: minimize or expand the toolbar</li></ul><h3 id="two-drawing-modes" tabindex="-1">Two Drawing Modes <a class="header-anchor" href="#two-drawing-modes" aria-label="Permalink to &quot;Two Drawing Modes&quot;">​</a></h3><ol><li><strong>Transparent mode</strong>: draw over any application or the desktop — ideal for screen annotation</li><li><strong>Whiteboard mode</strong>: a dedicated drawing space, perfect for board work and math</li></ol><p>Click the mode button on the toolbar to switch.</p><h3 id="gestures" tabindex="-1">Gestures <a class="header-anchor" href="#gestures" aria-label="Permalink to &quot;Gestures&quot;">​</a></h3><p>Touch devices support two-finger zoom, two-finger pan, two-finger tap to undo and more. See <a href="/website/en/guide/gestures-shortcuts">Gestures &amp; Shortcuts</a> for the full list and palm rejection settings.</p><h3 id="saving" tabindex="-1">Saving <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;Saving&quot;">​</a></h3><ul><li>Screenshot: saves the current view together with your ink as an image</li><li>Auto-save: periodically saves ink; see <a href="/website/en/guide/files-and-data">Files &amp; Data Locations</a> for paths</li></ul><h2 id="integration-with-powerpoint" tabindex="-1">Integration with PowerPoint <a class="header-anchor" href="#integration-with-powerpoint" aria-label="Permalink to &quot;Integration with PowerPoint&quot;">​</a></h2><p>ICC-CE lets you annotate slides while presenting and remembers ink per slide:</p><ol><li>Start PowerPoint and open your presentation</li><li>Enter slide show mode</li><li>ICC-CE detects the slide show and the toolbar gains slide navigation buttons</li><li>Ink is stored per slide and switches automatically as you navigate</li></ol><p>See the <a href="/website/en/guide/ppt-guide">PowerPoint Guide</a> for how the integration works, add-in setup and troubleshooting.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/website/en/guide/settings">Settings Guide</a> — common configuration options</li><li><a href="/website/en/guide/advanced-tips">Advanced Tips</a> — get more out of ICC-CE</li><li><a href="/website/en/guide/faq">FAQ</a> — start here when something goes wrong</li></ul>',25))])}const x=s(h,[["render",p]]);export{k as __pageData,x as default};
